462:       (keys.has('KeyD') || keys.has('ArrowRight') ? 1 : 0) - (keys.has('KeyA') || keys.has('ArrowLeft') ? 1 : 0),
463:       (keys.has('KeyW') || keys.has('ArrowUp') ? 1 : 0) - (keys.has('KeyS') || keys.has('ArrowDown') ? 1 : 0)
464:     );
465:     const input = moveInput.clone().add(keyboard);
466:     if (input.length() > 1) input.normalize();
467:     const forward = new THREE.Vector3(-Math.sin(yaw), 0, -Math.cos(yaw));
468:     const right = new THREE.Vector3(Math.cos(yaw), 0, -Math.sin(yaw));
469:     player.group.position.addScaledVector(forward, input.y * player.speed * dt);
470:     player.group.position.addScaledVector(right, input.x * player.speed * dt);
471:     player.group.position.x = THREE.MathUtils.clamp(player.group.position.x, -1.76, 1.76);
