:root {
  --blood: #e02525;
  --blood-bright: #ff3b30;
  --blood-deep: #740b10;
  --bone: #ece4d4;
  --ash: #a49c8d;
  --ink: #08080a;
  --panel: rgba(10, 10, 12, 0.72);
  --line: rgba(236, 228, 212, 0.16);
  --accent: #ffb15c;
  --font-display: Impact, Haettenschweiler, "Arial Narrow Bold", "Franklin Gothic Condensed", sans-serif;
  --font-ui: "Arial Narrow", "Roboto Condensed", "Helvetica Neue", Arial, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  background: #08080a;
  color: var(--bone);
  overflow: hidden;
  font-family: var(--font-ui);
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

#app { position: fixed; inset: 0; overflow: hidden; }

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
}

.grade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    repeating-linear-gradient(0deg, rgba(255,255,255,0.018) 0 1px, transparent 1px 3px);
  mix-blend-mode: overlay;
  opacity: 0.5;
}

.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 45%, transparent 42%, rgba(0,0,0,0.55) 100%),
    linear-gradient(180deg, rgba(0,0,0,0.35), transparent 22%, transparent 76%, rgba(0,0,0,0.6));
}

#hurt-flash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(ellipse at 50% 50%, transparent 30%, rgba(160, 8, 12, 0.72) 100%);
  transition: opacity 0.28s ease-out;
  z-index: 4;
}
#hurt-flash.on { opacity: 1; transition: none; }

.hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 5;
  padding: calc(18px + env(safe-area-inset-top)) calc(20px + env(safe-area-inset-right)) calc(16px + env(safe-area-inset-bottom)) calc(20px + env(safe-area-inset-left));
  opacity: 0;
  transition: opacity 0.45s ease;
}
body.playing .hud { opacity: 1; }

.tag {
  font-size: 9px;
  letter-spacing: 0.26em;
  color: var(--ash);
  font-weight: 700;
}

/* ---------- brand ---------- */
.brand { position: absolute; top: inherit; left: inherit; line-height: 1; }
.brand-mark {
  font-family: var(--font-display);
  font-size: 30px;
  letter-spacing: 0.06em;
  color: var(--bone);
  text-shadow: 0 2px 0 rgba(0,0,0,0.6);
}
.brand-mark span { color: var(--blood); margin-left: 3px; }
.brand-sub {
  margin-top: 5px;
  font-size: 8px;
  letter-spacing: 0.24em;
  color: rgba(236,228,212,0.48);
  font-weight: 700;
}

/* ---------- vitals ---------- */
.vitals {
  position: absolute;
  left: inherit;
  bottom: 92px;
  width: 248px;
  padding: 10px 12px 9px;
  background: linear-gradient(90deg, var(--panel), rgba(10,10,12,0.25));
  border-left: 2px solid var(--blood);
  backdrop-filter: blur(6px);
}
.vitals-head { display: flex; align-items: baseline; justify-content: space-between; }
#hp-number { font-family: var(--font-display); font-size: 26px; letter-spacing: 0.04em; line-height: 1; }
.hp-track {
  position: relative;
  height: 10px;
  margin-top: 6px;
  background: rgba(255,255,255,0.07);
  overflow: hidden;
  clip-path: polygon(0 0, 100% 0, calc(100% - 5px) 100%, 0 100%);
}
.hp-fill {
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, #8f0d14, var(--blood) 60%, #ff6a4a);
  box-shadow: 0 0 14px rgba(224,37,37,0.55);
  transition: width 0.16s linear;
}
.hp-ticks {
  position: absolute; inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 19px, rgba(0,0,0,0.42) 19px 21px);
}
.vitals-foot {
  margin-top: 6px;
  display: flex;
  justify-content: space-between;
  font-size: 8px;
  letter-spacing: 0.18em;
  color: rgba(236,228,212,0.5);
  font-weight: 700;
}
#state-label { color: var(--accent); }

/* ---------- score ---------- */
.score {
  position: absolute;
  right: inherit;
  top: inherit;
  text-align: right;
  min-width: 120px;
}
.score-row { display: flex; gap: 12px; align-items: baseline; justify-content: flex-end; }
.score-row b {
  font-family: var(--font-display);
  font-size: 30px;
  line-height: 0.95;
  font-weight: 400;
  letter-spacing: 0.04em;
}
.score-row + .score-row b { font-size: 22px; color: var(--blood); }
.feed {
  margin-top: 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: flex-end;
  font-size: 9px;
  letter-spacing: 0.14em;
  color: rgba(236,228,212,0.6);
  font-weight: 700;
}
.feed div { animation: feedIn 0.25s ease-out both; }
.feed b { color: var(--blood-bright); }
@keyframes feedIn { from { opacity: 0; transform: translateX(8px); } }

/* ---------- weapon card ---------- */
.weapon-card {
  position: absolute;
  right: inherit;
  bottom: 24px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 13px 9px 10px;
  background: linear-gradient(270deg, var(--panel), rgba(10,10,12,0.18));
  border-right: 2px solid var(--accent);
  backdrop-filter: blur(6px);
  min-width: 196px;
}
.weapon-icon { width: 40px; height: 40px; display: grid; place-items: center; color: var(--bone); }
.weapon-icon svg { width: 38px; height: 38px; display: block; filter: drop-shadow(0 0 6px rgba(255,177,92,0.25)); }
.weapon-name { font-family: var(--font-display); font-size: 21px; letter-spacing: 0.06em; line-height: 1; }
.weapon-stats {
  display: flex; justify-content: space-between; gap: 10px;
  margin-top: 4px;
  font-size: 8px; letter-spacing: 0.16em; color: rgba(236,228,212,0.55); font-weight: 700;
}
.weapon-bar { height: 3px; margin-top: 6px; background: rgba(255,255,255,0.1); width: 100%; }
.weapon-bar i { display: block; height: 100%; width: 40%; background: var(--accent); transition: width 0.2s; }

/* ---------- crosshair ---------- */
.crosshair {
  position: absolute;
  left: 50%; top: 50%;
  width: 40px; height: 40px;
  transform: translate(-50%, -50%);
  transition: opacity 0.2s;
}
.crosshair i { position: absolute; background: rgba(236,228,212,0.85); box-shadow: 0 0 4px rgba(0,0,0,0.9); }
.ch-t { left: 19px; top: 4px; width: 2px; height: 8px; }
.ch-b { left: 19px; bottom: 4px; width: 2px; height: 8px; }
.ch-l { left: 4px; top: 19px; width: 8px; height: 2px; }
.ch-r { right: 4px; top: 19px; width: 8px; height: 2px; }
.ch-dot { left: 19px; top: 19px; width: 2px; height: 2px; border-radius: 50%; }
.crosshair.hot i { background: var(--accent); }
.crosshair.hot { transform: translate(-50%, -50%) scale(1.12); }
.hitmarker { position: absolute; inset: 0; opacity: 0; }
.hitmarker::before, .hitmarker::after {
  content: ""; position: absolute; left: 20px; top: 8px; width: 1.5px; height: 24px;
  background: #ff4a3d; box-shadow: 0 0 6px #ff2a1a;
}
.hitmarker::before { transform: rotate(45deg); }
.hitmarker::after { transform: rotate(-45deg); }
.hitmarker.show { animation: hitpop 0.22s ease-out; }
@keyframes hitpop { 0% { opacity: 1; transform: scale(0.7); } 100% { opacity: 0; transform: scale(1.15); } }

/* ---------- prompt ---------- */
.prompt {
  position: absolute;
  left: 50%;
  bottom: 132px;
  transform: translateX(-50%) translateY(8px);
  display: flex;
  align-items: center;
  gap: 9px;

