226:       // clamp inside the pit (soft bounce)
227:       if (p.x > 1.9) { p.x = 1.9; this.vel.x *= -0.4; }
228:       if (p.x < -1.9) { p.x = -1.9; this.vel.x *= -0.4; }
229:       if (p.z > 1.9) { p.z = 1.9; this.vel.z *= -0.4; }
230:       if (p.z < -1.9) { p.z = -1.9; this.vel.z *= -0.4; }
231: 
232:       if (this.hitCooldown <= 0 && this.vel.lengthSq() > 5) {
233:         for (const npc of game.npcs) {
234:           if (!npc.alive || npc.state === 'grabbed' || npc.state === 'dead') continue;
235:           const d = npc.group.position.distanceTo(p);
236:           if (d < 0.48) {
237:             const dir = this.vel.clone().normalize();
238:             game.hitNPC(npc, this.def.throwDamage, dir, { weapon: this.kind, thrown: true });
239:             this.hitCooldown = 0.35;
240:             this.vel.multiplyScalar(-0.25);
241:             this.vel.y = 2;
242:             this.fx.bloodBurst(p, dir, 12, 1.2);
243:             game.shake(0.16);
244:             break;
245:           }
246:         }
247:       }
248:     }
249:   }
