145: 
146:     this.state = 'ground';
147:     this.vel = new THREE.Vector3();
148:     this.spin = new THREE.Vector3();
149:     this.hitCooldown = 0;
150:     this.baseY = 0.185;
151:     this.idle = Math.random() * 10;
152:     scene.add(this.group);
153:   }
154: 
155:   get worldPosition() {
156:     return this.group.getWorldPosition(new THREE.Vector3());
157:   }
158: 
159:   attach(anchor) {
160:     this.state = 'held';
161:     this.group.visible = false;
162:     this.ring.visible = false;
163:     this.group.rotation.set(0, 0, 0);
164:     this.group.position.set(0.02, 0, 0.04);
165:     anchor.add(this.group);
166:   }
167: 
168:   dropToGround(pos, yaw = 0) {
169:     this.state = 'ground';
170:     this.scene.attach(this.group);
171:     this.group.visible = true;
172:     this.group.position.copy(pos);
173:     this.group.position.y = this.baseY;
174:     this.group.rotation.set(0, yaw, 0);
175:     this.ring.visible = true;
176:     this.hitCooldown = 0;
177:     this.fx.ring(this.group.position, 0xffa347, 0.32, 0.35);
178:   }
179: 
180:   throwFrom(pos, dir) {
181:     this.state = 'thrown';
182:     this.group.visible = true;
183:     this.ring.visible = false;
184:     this.scene.attach(this.group);
185:     this.group.position.copy(pos);
186:     this.group.rotation.set(Math.random() * 2, Math.random() * 2, Math.random() * 2);
187:     this.vel.set(dir.x * 8.2, 3.4, dir.z * 8.2);
188:     this.spin.set(rand(-10, 10), rand(-10, 10), rand(-10, 10));
189:     this.hitCooldown = 0.08;
190:   }
191: 
192:   update(dt, time, game) {
193:     this.hitCooldown = Math.max(0, this.hitCooldown - dt);
194:     if (this.state === 'ground') {
195:       this.idle += dt;
196:       this.group.position.y = this.baseY + Math.sin(this.idle * 2.2) * 0.012;
197:       this.group.rotation.y += dt * 0.55;
198:       this.ring.material.opacity = 0.38 + Math.sin(this.idle * 2.6) * 0.16;
199:       this.ring.scale.setScalar(1 + Math.sin(this.idle * 2.6) * 0.06);
200:     } else if (this.state === 'thrown') {
201:       this.vel.y -= 17 * dt;
202:       this.group.position.addScaledVector(this.vel, dt);
203:       this.group.rotation.x += this.spin.x * dt;
204:       this.group.rotation.y += this.spin.y * dt;
205:       this.group.rotation.z += this.spin.z * dt;
206: 
207:       const p = this.group.position;
208:       if (p.y < this.baseY) {
209:         p.y = this.baseY;
210:         if (Math.abs(this.vel.y) > 1.2) {
211:           this.vel.y *= -0.42;
212:           this.vel.x *= 0.72;
213:           this.vel.z *= 0.72;
214:           this.spin.multiplyScalar(0.72);
215:           if (Math.random() < 0.5) this.fx.bloodBurst(p, new THREE.Vector3(0, 1, 0), 3, 0.4);
216:         } else {
217:           this.state = 'ground';
218:           this.idle = 0;
219:           this.group.rotation.set(0, this.group.rotation.y, 0);
220:           this.group.position.y = this.baseY;
221:           this.ring.visible = true;
222:           this.fx.ring(p, 0xffa347, 0.35, 0.4);
223:         }
224:       }
225: 
226:       // clamp inside the pit (soft bounce)
227:       if (p.x > 1.9) { p.x = 1.9; this.vel.x *= -0.4; }
228:       if (p.x < -1.9) { p.x = -1.9; this.vel.x *= -0.4; }
229:       if (p.z > 1.9) { p.z = 1.9; this.vel.z *= -0.4; }
230:       if (p.z < -1.9) { p.z = -1.9; this.vel.z *= -0.4; }
231: 
232:       if (this.hitCooldown <= 0 && this.vel.lengthSq() > 5) {
233:         for (const npc of game.npcs) {
234:           if (!npc.alive || npc.state === 'grabbed' || npc.state === 'dead') continue;
235:           const d = npc.group.position.distanceTo(p);
236:           if (d < 0.48) {
237:             const dir = this.vel.clone().normalize();
238:             game.hitNPC(npc, this.def.throwDamage, dir, { weapon: this.kind, thrown: true });
239:             this.hitCooldown = 0.35;
240:             this.vel.multiplyScalar(-0.25);
241:             this.vel.y = 2;
242:             this.fx.bloodBurst(p, dir, 12, 1.2);
243:             game.shake(0.16);
244:             break;
245:           }
246:         }
247:       }
248:     }
249:   }
250: }
