222: function nearestTarget(maxDist = 1.65) {
223:   const p = player.group.position;
224:   let best = null, bestScore = Infinity;
225:   const consider = (obj, point, type) => {
226:     const dx = point.x - p.x, dz = point.z - p.z;
227:     const dist = Math.hypot(dx, dz);
228:     if (dist > maxDist) return;
229:     const dot = (dx * player.forward.x + dz * player.forward.z) / Math.max(dist, 0.001);
230:     if (dot < -0.25) return;
231:     const score = dist + (dot < 0.15 ? 0.55 : 0);
232:     if (score < bestScore) { best = { obj, type, dist }; bestScore = score; }
233:   };
234:   for (const npc of npcs) if (npc.alive && npc.state !== 'grabbed') consider(npc, npc.group.position, 'npc');
235:   for (const weapon of weapons) if (weapon.state === 'ground') consider(weapon, weapon.group.position, 'weapon');
236:   return best;
237: }
