455: function updateStick(event) {
456:   const rect = stick.getBoundingClientRect();
457:   const radius = rect.width * 0.34;
458:   const dx = event.clientX - (rect.left + rect.width * 0.5);
459:   const dy = event.clientY - (rect.top + rect.height * 0.5);
460:   const len = Math.hypot(dx, dy);
461:   const scale = len > radius ? radius / len : 1;
462:   const x = dx * scale;
463:   const y = dy * scale;
464:   stickKnob.style.transform = `translate(${x}px, ${y}px)`;
465:   moveInput.set(x / radius, -y / radius);
466:   if (moveInput.length() > 1) moveInput.normalize();
467: }
468: stick.addEventListener('pointerdown', event => {
469:   event.preventDefault();
470:   stickPointer = event.pointerId;
471:   stick.setPointerCapture(event.pointerId);
472:   updateStick(event);
473: });
474: stick.addEventListener('pointermove', event => {
475:   if (event.pointerId === stickPointer) updateStick(event);
476: });
477: function releaseStick(event) {
478:   if (event.pointerId !== stickPointer) return;
479:   stickPointer = null;
