498: function update(dt) {
499:   time += dt;
500:   game.time = time;
501:   const playing = document.body.classList.contains('playing') && player.alive;
502:   hitCooldown = Math.max(0, hitCooldown - dt);
503:   swingT = Math.max(0, swingT - dt);
504: 
505:   player.group.rotation.y = yaw;
506:   player.forward.set(-Math.sin(yaw), 0, -Math.cos(yaw));
507:   camera.rotation.x = pitch;
508: 
509:   if (playing) {
510:     const keyboard = new THREE.Vector2(
511:       (keys.has('KeyD') || keys.has('ArrowRight') ? 1 : 0) - (keys.has('KeyA') || keys.has('ArrowLeft') ? 1 : 0),
512:       (keys.has('KeyW') || keys.has('ArrowUp') ? 1 : 0) - (keys.has('KeyS') || keys.has('ArrowDown') ? 1 : 0)
513:     );
514:     const input = moveInput.clone().add(keyboard);
515:     if (input.length() > 1) input.normalize();
516:     const forward = new THREE.Vector3(-Math.sin(yaw), 0, -Math.cos(yaw));
517:     const right = new THREE.Vector3(Math.cos(yaw), 0, -Math.sin(yaw));
518:     player.group.position.addScaledVector(forward, input.y * player.speed * dt);
519:     player.group.position.addScaledVector(right, input.x * player.speed * dt);
520:     player.group.position.x = THREE.MathUtils.clamp(player.group.position.x, -1.76, 1.76);
521:     player.group.position.z = THREE.MathUtils.clamp(player.group.position.z, -1.76, 1.76);
522:   }
523: 
524:   if (heldNPC && player.alive) heldNPC.setGrabbed(player);
525:   for (const npc of npcs) npc.update(dt, game);
526:   for (const weapon of weapons) weapon.update(dt, time, game);
527:   fx.update(dt, time);
528: 
529:   const targetArm = swingT > 0 ? -1.25 * (swingT / 0.24) : 0;
530:   armR.rotation.x += (targetArm - armR.rotation.x) * Math.min(1, dt * 18);
531:   armL.rotation.x += ((heldNPC ? -0.5 : 0) - armL.rotation.x) * Math.min(1, dt * 10);
532:   if (viewWeapon) viewWeapon.rotation.x = -0.2 + (swingT > 0 ? -0.7 * (swingT / 0.24) : 0);
533: 
534:   if (shakeT > 0) {
535:     const amount = shakeT;
536:     camera.position.set((Math.random() - 0.5) * amount * 0.16, 1.62 + (Math.random() - 0.5) * amount * 0.12, 0);
537:     camera.rotation.z = (Math.random() - 0.5) * amount * 0.1;
538:     shakeT = Math.max(0, shakeT - dt * 1.8);
539:   } else {
540:     camera.position.set(0, 1.62, 0);
541:     camera.rotation.z = 0;
542:   }
543: 
544:   updatePrompt();
545:   updateHud();
546:   renderer.render(scene, camera);
547: }
