255: function nearestTarget(maxDist = 1.65) {
256:   const p = player.group.position;
257:   let best = null, bestScore = Infinity;
258:   const consider = (obj, point, type) => {
259:     const dx = point.x - p.x, dz = point.z - p.z;
260:     const dist = Math.hypot(dx, dz);
261:     if (dist > maxDist) return;
262:     const dot = (dx * player.forward.x + dz * player.forward.z) / Math.max(dist, 0.001);
263:     if (dot < -0.25) return;
264:     const score = dist + (dot < 0.15 ? 0.55 : 0);
265:     if (score < bestScore) { best = { obj, type, dist }; bestScore = score; }
266:   };
267:   for (const npc of npcs) if (npc.alive && npc.state !== 'grabbed') consider(npc, npc.group.position, 'npc');
268:   for (const weapon of weapons) if (weapon.state === 'ground') consider(weapon, weapon.group.position, 'weapon');
269:   return best;
270: }
