171:     this.group.visible = true;
172:     this.group.position.copy(pos);
173:     this.group.position.y = this.baseY;
174:     this.group.rotation.set(0, yaw, 0);
175:     this.ring.visible = true;
176:     this.hitCooldown = 0;
177:     this.fx.ring(this.group.position, 0xffa347, 0.32, 0.35);
178:   }
