18:     if (distanceSq < 1e-8) {
19:       const left = Math.abs(position.x - box.minX);
20:       const right = Math.abs(box.maxX - position.x);
21:       const near = Math.abs(position.z - box.minZ);
22:       const far = Math.abs(box.maxZ - position.z);
23:       const edge = Math.min(left, right, near, far);
24:       if (edge === left) { dx = -1; dz = 0; }
25:       else if (edge === right) { dx = 1; dz = 0; }
