256: function nearestTarget(maxDist = 1.65) {
257:   const p = player.group.position;
258:   let best = null, bestScore = Infinity;
259:   const consider = (obj, point, type) => {
260:     const dx = point.x - p.x, dz = point.z - p.z;
261:     const dist = Math.hypot(dx, dz);
262:     if (dist > maxDist) return;
263:     const dot = (dx * player.forward.x + dz * player.forward.z) / Math.max(dist, 0.001);
264:     if (dot < -0.25) return;
265:     const score = dist + (dot < 0.15 ? 0.55 : 0);
266:     if (score < bestScore) { best = { obj, type, dist }; bestScore = score; }
267:   };
268:   for (const npc of npcs) if (npc.alive && npc.state !== 'grabbed') consider(npc, npc.group.position, 'npc');
269:   for (const weapon of weapons) if (weapon.state === 'ground') consider(weapon, weapon.group.position, 'weapon');
270:   return best;
271: }
