350:     const dx = npc.group.position.x - origin.x, dz = npc.group.position.z - origin.z;
351:     const dist = Math.hypot(dx, dz);
352:     if (dist > def.range + (npc.baseScale * 0.22)) continue;
353:     const dot = (dx * player.forward.x + dz * player.forward.z) / Math.max(dist, 0.001);
354:     if (dot < 0.28) continue;
355:     if (dist < best) { target = npc; best = dist; }
