489: function updateStick(event) {
490:   const rect = stick.getBoundingClientRect();
491:   const radius = rect.width * 0.34;
492:   const dx = event.clientX - (rect.left + rect.width * 0.5);
493:   const dy = event.clientY - (rect.top + rect.height * 0.5);
494:   const len = Math.hypot(dx, dy);
495:   const scale = len > radius ? radius / len : 1;
496:   const x = dx * scale;
497:   const y = dy * scale;
498:   stickKnob.style.transform = `translate(${x}px, ${y}px)`;
499:   moveInput.set(x / radius, -y / radius);
500:   if (moveInput.length() > 1) moveInput.normalize();
501: }
502: stick.addEventListener('pointerdown', event => {
503:   event.preventDefault();
504:   stickPointer = event.pointerId;
505:   stick.setPointerCapture(event.pointerId);
506:   updateStick(event);
507: });
508: stick.addEventListener('pointermove', event => {
509:   if (event.pointerId === stickPointer) updateStick(event);
510: });
511: function releaseStick(event) {
512:   if (event.pointerId !== stickPointer) return;
513:   stickPointer = null;
514:   moveInput.set(0, 0);
