3: // Keep a circular actor inside the active map and push it out of solid X/Z boxes.
4: export function resolveWorldPosition(position, radius, bounds, solids = [], velocity = null) {
5:   const limitX = Math.max(0, bounds.x - radius);
6:   const limitZ = Math.max(0, bounds.z - radius);
7:   position.x = THREE.MathUtils.clamp(position.x, -limitX, limitX);
8:   position.z = THREE.MathUtils.clamp(position.z, -limitZ, limitZ);
9: 
10:   for (const box of solids) {
11:     const nearestX = THREE.MathUtils.clamp(position.x, box.minX, box.maxX);
12:     const nearestZ = THREE.MathUtils.clamp(position.z, box.minZ, box.maxZ);
13:     let dx = position.x - nearestX;
14:     let dz = position.z - nearestZ;
15:     const distanceSq = dx * dx + dz * dz;
16:     if (distanceSq >= radius * radius) continue;
17: 
18:     if (distanceSq < 1e-8) {
19:       const left = Math.abs(position.x - box.minX);
20:       const right = Math.abs(box.maxX - position.x);
21:       const near = Math.abs(position.z - box.minZ);
22:       const far = Math.abs(box.maxZ - position.z);
23:       const edge = Math.min(left, right, near, far);
24:       if (edge === left) { dx = -1; dz = 0; }
25:       else if (edge === right) { dx = 1; dz = 0; }
26:       else if (edge === near) { dx = 0; dz = -1; }
27:       else { dx = 0; dz = 1; }
28:       position.x += dx * (radius + edge);
29:       position.z += dz * (radius + edge);
30:     } else {
31:       const distance = Math.sqrt(distanceSq);
32:       dx /= distance; dz /= distance;
33:       const push = radius - distance;
34:       position.x += dx * push;
35:       position.z += dz * push;
36:     }
37:     if (velocity) {
38:       if (Math.abs(dx) > Math.abs(dz)) velocity.x *= -0.35;
39:       else velocity.z *= -0.35;
40:     }
41:   }
42:   position.x = THREE.MathUtils.clamp(position.x, -limitX, limitX);
43:   position.z = THREE.MathUtils.clamp(position.z, -limitZ, limitZ);
44:   return position;
