317: function attack() {
318:   if (!player.alive) return;
319:   if (!heldWeapon) {
320:     if (shotCooldown > 0) return;
321:     shotCooldown = 0.3;
322:     audio.pistol();
323:     swingT = 0.12;
324:     let target = null, bestAlong = Infinity;
325:     const origin = player.group.position;
326:     for (const npc of npcs) {
327:       if (!npc.alive || npc.state === 'grabbed') continue;
328:       const dx = npc.group.position.x - origin.x, dz = npc.group.position.z - origin.z;
329:       const along = dx * player.forward.x + dz * player.forward.z;
330:       const lateral = Math.abs(dx * player.forward.z - dz * player.forward.x);
331:       if (along < 0 || along > 24 || lateral > 0.38 + along * 0.018) continue;
332:       if (along < bestAlong) { target = npc; bestAlong = along; }
333:     }
334:     if (target) {
335:       game.hitNPC(target, 34, player.forward, { weapon: 'pistol' });
336:       fx.bloodBurst(target.group.position.clone().setY(1.08), player.forward, 10, 0.75);
337:     }
338:     return;
339:   }
340:   if (hitCooldown > 0) return;
341:   const kind = heldWeapon?.kind || 'fist';
342:   const def = WEAPON_DEFS[kind];
343:   hitCooldown = def.cooldown;
344:   swingT = 0.24;
345:   if (kind === 'fist') audio.punch(); else audio.swing();
346:   const origin = player.group.position;
347:   let target = null, best = Infinity;
348:   for (const npc of npcs) {
349:     if (!npc.alive || npc.state === 'grabbed') continue;
350:     const dx = npc.group.position.x - origin.x, dz = npc.group.position.z - origin.z;
351:     const dist = Math.hypot(dx, dz);
352:     if (dist > def.range + (npc.baseScale * 0.22)) continue;
353:     const dot = (dx * player.forward.x + dz * player.forward.z) / Math.max(dist, 0.001);
354:     if (dot < 0.28) continue;
355:     if (dist < best) { target = npc; best = dist; }
356:   }
357:   if (target) {
358:     game.hitNPC(target, def.damage, player.forward, { weapon: kind });
359:     fx.bloodBurst(target.group.position.clone().setY(1.08), player.forward, kind === 'fist' ? 8 : 13, kind === 'fist' ? 0.65 : 1.05);
360:     if (kind !== 'fist') fx.slash(target.group.position.clone(), yaw, kind === 'pickaxe' ? 0xffb15c : 0xe9d2bc);
361:     if (kind !== 'fist') audio.hit();
