552:     player.group.position.addScaledVector(forward, input.y * player.speed * dt);
553:     player.group.position.addScaledVector(right, input.x * player.speed * dt);
554:     player.group.position.x = THREE.MathUtils.clamp(player.group.position.x, -1.76, 1.76);
