320:     if (shotCooldown > 0) return;
321:     shotCooldown = 0.3;
322:     audio.pistol();
323:     swingT = 0.12;
324:     let target = null, bestAlong = Infinity;
325:     const origin = player.group.position;
326:     for (const npc of npcs) {
327:       if (!npc.alive || npc.state === 'grabbed') continue;
328:       const dx = npc.group.position.x - origin.x, dz = npc.group.position.z - origin.z;
329:       const along = dx * player.forward.x + dz * player.forward.z;
330:       const lateral = Math.abs(dx * player.forward.z - dz * player.forward.x);
331:       if (along < 0 || along > 24 || lateral > 0.38 + along * 0.018) continue;
332:       if (along < bestAlong) { target = npc; bestAlong = along; }
333:     }
334:     if (target) {
335:       game.hitNPC(target, 34, player.forward, { weapon: 'pistol' });
336:       fx.bloodBurst(target.group.position.clone().setY(1.08), player.forward, 10, 0.75);
